<template><div><div class="page-head"><div><h1 class="page-title">我的预约</h1><p class="page-subtitle">查看练琴安排，退约后时段会立即释放。</p></div><el-button type="primary" @click="router.push('/rooms')">去预约</el-button></div><el-card class="soft-card" shadow="never"><el-tabs v-model="status" @tab-change="load"><el-tab-pane label="全部" name=""/><el-tab-pane label="已预约" name="booked"/><el-tab-pane label="已取消" name="cancelled"/><el-tab-pane label="已完成" name="finished"/></el-tabs><el-table v-if="items.length" :data="items" stripe><el-table-column label="琴房" min-width="150"><template #default="{row}">{{ roomName(row.roomId) }}</template></el-table-column><el-table-column label="日期" prop="bookDate" width="125"/><el-table-column label="时段" width="150"><template #default="{row}">{{ timeRange(row) }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='booked'?'success':row.status==='cancelled'?'info':'warning'">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button v-if="row.status==='booked'" link type="danger" @click="cancel(row)">退约</el-button></template></el-table-column></el-table><el-empty v-else-if="!loading" description="暂无预约记录"/><div class="pager"><el-pagination v-if="total" v-model:current-page="page" layout="total, prev, pager, next" :total="total" :page-size="10" @current-change="load"/></div></el-card></div></template>
<script setup>
import { onMounted, ref } from 'vue'; import { ElMessage, ElMessageBox } from 'element-plus'; import { useRouter } from 'vue-router'; import { listBookings, cancelBooking } from '../api/bookings'; import { listRooms } from '../api/rooms'; import { minuteToTime, statusLabel, timeRange } from '../utils/time'
const router=useRouter();const status=ref('');const items=ref([]);const total=ref(0);const page=ref(1);const loading=ref(false);const rooms=ref({});const cancelling=ref(false)
function roomName(id){return rooms.value[id]||`琴房 #${id}`};async function loadRooms(){try{const d=await listRooms({page:1,size:100});(d?.list||[]).forEach(r=>{rooms.value[r.id]=r.name})}catch{} };async function load(){loading.value=true;try{const d=await listBookings({status:status.value||undefined,page:page.value,size:10});items.value=d?.list||[];total.value=d?.total||0}catch(e){ElMessage.error(e.message)}finally{loading.value=false}};async function cancel(row){if(cancelling.value)return;try{await ElMessageBox.confirm(`确认取消 ${roomName(row.roomId)} ${row.bookDate} ${timeRange(row)}？`,'退约确认',{type:'warning',confirmButtonText:'确认退约',cancelButtonText:'再想想'});cancelling.value=true;await cancelBooking(row.id);ElMessage.success('已取消预约');await load()}catch(e){if(e!=='cancel'&&e!=='close'&&e?.message)ElMessage.warning(e.message)}finally{cancelling.value=false}};onMounted(()=>{loadRooms();load()})
</script>
<style scoped>.pager{display:flex;justify-content:center;padding-top:20px}.el-tabs{margin-bottom:12px}@media(max-width:768px){.el-table{overflow-x:auto}.page-head{gap:8px}}</style>
